package com.primehr.rewardsrecognition.api;
import com.primehr.rewardsrecognition.api.RrNominationDtos.*;import com.primehr.rewardsrecognition.application.RrNominationService;import com.primehr.rewardsrecognition.domain.RrNominationEvidence;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api/primehr/v1/rewards-recognition")
public class RrNominationController{private final RrNominationService service;private final RrNominationPermissionGuard permission;private final AgencyScopeResolver agency;public RrNominationController(RrNominationService s,RrNominationPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}private String agency(Authentication a){return agency.resolveAgencyId(a);}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated employee identity is required");return a.getName();}
 @GetMapping("/cycles")public List<CycleResponse>cycles(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(RrNominationPermissionGuard.CYCLE,PrimeHrAction.ACCESS,token);return service.cycles(agency(a));}
 @GetMapping("/cycles/{id}")public CycleResponse cycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){permission.require(RrNominationPermissionGuard.CYCLE,PrimeHrAction.ACCESS,token);return service.cycle(agency(a),id);}
 @PostMapping("/cycles")@ResponseStatus(HttpStatus.CREATED)public CycleResponse createCycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody CycleInput in){permission.require(RrNominationPermissionGuard.CYCLE,PrimeHrAction.ADD,token);return service.createCycle(agency(a),in,c);}
 @PutMapping("/cycles/{id}")public CycleResponse updateCycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody CycleInput in){permission.require(RrNominationPermissionGuard.CYCLE,PrimeHrAction.EDIT,token);return service.updateCycle(agency(a),id,in,c);}
 @PostMapping("/cycles/{id}/{action:open|close|cancel}")public CycleResponse transitionCycle(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String action,@Valid@RequestBody Transition in){permission.require(RrNominationPermissionGuard.CYCLE,"open".equals(action)?PrimeHrAction.SUBMIT:PrimeHrAction.FINALIZE,token);return service.transitionCycle(agency(a),id,in,action,c);}
 @GetMapping("/nominations")public List<NominationResponse>nominations(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){return service.nominations(agency(a),actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token));}
 @GetMapping("/nominations/{id}")public NominationResponse nomination(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){return service.nomination(agency(a),id,actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token));}
 @PostMapping("/nominations")@ResponseStatus(HttpStatus.CREATED)public NominationResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody NominationInput in){return service.createNomination(agency(a),in,token,actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.ADD,token),c);}
 @PutMapping("/nominations/{id}")public NominationResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody NominationInput in){return service.updateNomination(agency(a),id,in,token,actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.EDIT,token),c);}
 @PostMapping("/nominations/{id}/submit")public NominationResponse submit(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody Transition in){return service.submit(agency(a),id,in,actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.SUBMIT,token),c);}
 @PostMapping("/nominations/{id}/withdraw")public NominationResponse withdraw(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody Transition in){return service.withdraw(agency(a),id,in,actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.ARCHIVE,token),c);}
 @PostMapping(value="/nominations/{id}/evidence",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@ResponseStatus(HttpStatus.CREATED)public EvidenceResponse upload(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@RequestParam String title,@RequestParam RrNominationEvidence.Visibility visibility,@RequestPart("file")MultipartFile file){return service.upload(agency(a),id,title,visibility,file,actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.EDIT,token),c);}
 @GetMapping("/nominations/{id}/evidence/{evidenceId}/content")public ResponseEntity<InputStreamResource>download(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String evidenceId){var v=service.download(agency(a),id,evidenceId,actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.ACCESS,token),c);return ResponseEntity.ok().contentType(MediaType.parseMediaType(v.mediaType())).contentLength(v.size()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(v.filename()).build().toString()).header(HttpHeaders.CACHE_CONTROL,"no-store").header("X-Content-Type-Options","nosniff").body(new InputStreamResource(v.stream()));}
 @DeleteMapping("/nominations/{id}/evidence/{evidenceId}")public NominationResponse deleteEvidence(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String evidenceId,@RequestParam Long recordVersion){return service.deleteDraftEvidence(agency(a),id,evidenceId,recordVersion,actor(a),permission.require(RrNominationPermissionGuard.NOMINATION,PrimeHrAction.EDIT,token),c);}
}
